import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { Brain } from 'lucide-react';

const DEMO_USERS = [
  { role: 'student', id: 1, name: 'Arjun Kumar',    label: 'Student',  sub: 'View your courses & grades' },
  { role: 'teacher', id: 1, name: 'Dr. Riya Sharma', label: 'Teacher', sub: 'Manage classes & grade work' },
  { role: 'admin',   id: 0, name: 'Admin',           label: 'Admin',   sub: 'Platform-wide overview' },
];

export default function Login() {
  const { login } = useAuth();
  const navigate  = useNavigate();
  const [selected, setSelected] = useState(null);

  const handleLogin = () => {
    if (!selected) return;
    login(selected.role, selected.id, selected.name);
    navigate(`/${selected.role}`);
  };

  return (
    <div className="min-h-screen bg-gray-50 flex items-center justify-center p-6">
      <div className="w-full max-w-sm">
        {/* Header */}
        <div className="text-center mb-8">
          <div className="w-12 h-12 rounded-2xl bg-brand-600 flex items-center justify-center mx-auto mb-4">
            <Brain size={24} color="white" />
          </div>
          <h1 className="text-xl font-medium text-gray-900">AI Learning Platform</h1>
          <p className="text-sm text-gray-400 mt-1">ai_learning_platform · DBMS Mini Project</p>
        </div>

        {/* Role cards */}
        <div className="flex flex-col gap-3 mb-5">
          {DEMO_USERS.map(u => (
            <button
              key={u.role}
              onClick={() => setSelected(u)}
              className={`flex items-center gap-4 p-4 rounded-2xl border text-left transition-all
                ${selected?.role === u.role
                  ? 'border-brand-600 bg-brand-50'
                  : 'border-gray-200 bg-white hover:border-gray-300'}`}
            >
              <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-sm font-medium
                ${selected?.role === u.role ? 'bg-brand-600 text-white' : 'bg-gray-100 text-gray-600'}`}>
                {u.name.split(' ').map(n => n[0]).join('').toUpperCase().slice(0, 2)}
              </div>
              <div>
                <p className="text-sm font-medium text-gray-900">{u.label}</p>
                <p className="text-xs text-gray-400">{u.sub}</p>
              </div>
            </button>
          ))}
        </div>

        <button
          onClick={handleLogin}
          disabled={!selected}
          className={`w-full py-2.5 rounded-xl text-sm font-medium transition-all
            ${selected
              ? 'bg-brand-600 text-white hover:bg-brand-800'
              : 'bg-gray-100 text-gray-300 cursor-not-allowed'}`}
        >
          Continue as {selected?.label ?? '…'}
        </button>

        <p className="text-center text-xs text-gray-400 mt-4">Demo — no real auth required</p>
      </div>
    </div>
  );
}
